# frozen_string_literal: true

module RuboCop
  module Cop
    module Lint
      # The safe navigation operator returns nil if the receiver is
      # nil. If you chain an ordinary method call after a safe
      # navigation operator, it raises NoMethodError. We should use a
      # safe navigation operator after a safe navigation operator.
      # This cop checks for the problem outlined above.
      #
      # @example
      #
      #   # bad
      #   x&.foo.bar
      #   x&.foo + bar
      #   x&.foo[bar]
      #
      #   # good
      #   x&.foo&.bar
      #   x&.foo || bar
      class SafeNavigationChain < Base
        include NilMethods
        extend AutoCorrector
        extend TargetRubyVersion

        minimum_target_ruby_version 2.3

        MSG = 'Do not chain ordinary method call after safe navigation operator.'
        PLUS_MINUS_METHODS = %i[+@ -@].freeze
        STYLE_LOGIC_JUMP_KEYWORDS = %i[break fail next raise return throw yield].freeze
        REDUNDANT_MSG = 'Redundant safe navigation detected, use `.` instead.'
        REDUNDANT_MSG_LITERAL = 'Redundant safe navigation with default literal detected.'
        NIL_SPECIFIC_METHODS = (nil.methods - Object.new.methods).to_set.freeze
        SNAKE_CASE = /\A[[:digit:][:upper:]_]+\z/.freeze
        USE_DOT_MSG = 'Use `.` instead of unnecessary `&.`.'
        USE_SAFE_NAVIGATION_MSG = 'Use `&.` for consistency with safe navigation.'
        EMPTY_NAV_MSG = 'Avoid calling `empty?` with the safe navigation operator in conditionals.'
        CHAIN_LENGTH_MSG = 'Avoid safe navigation chains longer than %<max>d calls.'
        OPERATOR_CALL_MSG = 'Redundant dot detected.'
        OPERATOR_INVALID_ARG_TYPES = %i[
          splat kwsplat forwarded_args forwarded_restarg forwarded_kwrestarg block_pass
        ].freeze
        OMIT_PARENS_MSG = 'Omit parentheses for method calls with arguments.'
        REQUIRE_PARENS_MSG = 'Use parentheses for method calls with arguments.'
        WITHOUT_PARENS_MSG = 'Do not use parentheses for method calls with no arguments.'
        SPACE_DOT_MSG = 'Avoid using spaces around a method call operator.'
        SPACES_REGEXP = /\A[ \t]+\z/.freeze
        TRAILING_WHITESPACE_REGEX = /\s+\Z/.freeze
        AMBIGUOUS_MSG_FORMAT = 'Ambiguous %<actual>s operator. Parenthesize the method ' \
                               "arguments if it's surely a %<actual>s operator, or add " \
                               'a whitespace to the right of the `%<operator>s` if it ' \
                               'should be %<possible>s.'
        AMBIGUITIES = {
          '+' => { actual: 'positive number', possible: 'an addition', operator: '+' },
          '-' => { actual: 'negative number', possible: 'a subtraction', operator: '-' },
          '*' => { actual: 'splat', possible: 'a multiplication', operator: '*' },
          '&' => { actual: 'block', possible: 'a binary AND', operator: '&' },
          '**' => { actual: 'keyword splat', possible: 'an exponent', operator: '**' }
        }.freeze
        PRECEDENCE_GROUPS = [
          %i[**],
          %i[* / %],
          %i[+ -],
          %i[<< >>],
          %i[&],
          %i[| ^],
          %i[&&],
          %i[||]
        ].freeze
        PRECEDENCE_OPERATORS = PRECEDENCE_GROUPS.flatten.freeze
        PRECEDENCE_MSG = 'Wrap expressions with varying precedence with parentheses to avoid ambiguity.'

        # @!method bad_method?(node)
        def_node_matcher :bad_method?, <<~PATTERN
          {
            (send $(csend ...) $_ ...)
            (send $({block numblock} (csend ...) ...) $_ ...)
          }
        PATTERN

        # @!method style_modifier_if_candidate(node)
        def_node_matcher :style_modifier_if_candidate, <<~PATTERN
          {
            (if {
                  (send $_ {:nil? :!})
                  $_
                } nil? $_)

            (if {
                  (send (send $_ :nil?) :!)
                  $_
                } $_ nil?)
          }
        PATTERN

        # @!method style_ternary_candidate(node)
        def_node_matcher :style_ternary_candidate, <<~PATTERN
          {
            (if (send $_ {:nil? :!}) nil $_)

            (if (send (send $_ :nil?) :!) $_ nil)

            (if $_ $_ nil)
          }
        PATTERN

        # @!method style_and_with_rhs_or?(node)
        def_node_matcher :style_and_with_rhs_or?, '(and _ {or (begin or)})'

        # @!method style_not_nil_check?(node)
        def_node_matcher :style_not_nil_check?, '(send (send $_ :nil?) :!)'

        # @!method style_and_inside_begin?(node)
        def_node_matcher :style_and_inside_begin?, '`(begin and ...)'

        # @!method style_strip_begin(node)
        def_node_matcher :style_strip_begin, '{ (begin $!begin) $!(begin) }'

        # @!method redundant_respond_to_nil_specific_method?(node)
        def_node_matcher :redundant_respond_to_nil_specific_method?, <<~PATTERN
          (csend _ :respond_to? (sym %NIL_SPECIFIC_METHODS))
        PATTERN

        # @!method redundant_conversion_with_default?(node)
        def_node_matcher :redundant_conversion_with_default?, <<~PATTERN
          {
            (or $(csend _ :to_h) (hash))
            (or (block $(csend _ :to_h) ...) (hash))
            (or $(csend _ :to_a) (array))
            (or $(csend _ :to_i) (int 0))
            (or $(csend _ :to_f) (float 0.0))
            (or $(csend _ :to_s) (str empty?))
          }
        PATTERN

        # @!method empty_nav_in_conditional?(node)
        def_node_matcher :empty_nav_in_conditional?, <<~PATTERN
          (if (csend (send ...) :empty?) ...)
        PATTERN

        def on_send(node)
          @nav_send = node
          return unless require_safe_navigation?(node)

          bad_method?(node) do |safe_nav, method|
            return if nil_methods.include?(method) || PLUS_MINUS_METHODS.include?(node.method_name)

            begin_range = node.loc.dot || safe_nav.source_range.end
            location = begin_range.join(node.source_range.end)

            add_offense(location) do |corrector|
              autocorrect(corrector, offense_range: location, send_node: node)
            end
          end
        end

        def run_style_if(host, node)
          @style_host = host
          @style_node = node
          @style_chain = node
          return if style_allowed_if_condition?(node)

          checked_variable, receiver, method_chain, _method = style_extract_parts_from_if(node)
          return unless style_offending_node?(node, checked_variable, method_chain, receiver)

          body = style_extract_if_body(node)
          method_call = receiver.parent
          removal_ranges = [style_begin_range(node, body), style_end_range(node, body)]

          style_report_offense(node, method_chain, method_call, *removal_ranges) do |corrector|
            corrector.insert_before(method_call.loc.dot, '&') unless method_call.safe_navigation?
          end
        end

        def run_style_and(host, node)
          @style_host = host
          @style_node = node
          @style_chain = node
          style_collect_and_clauses(node).each do |(lhs, lhs_operator_range), (rhs, _rhs_operator_range)|
            lhs_not_nil_check = style_not_nil_check?(lhs)
            lhs_receiver = lhs_not_nil_check || lhs
            rhs_receiver = style_find_matching_receiver_invocation(style_strip_begin(rhs), lhs_receiver)

            next if !@style_host.send(:cop_config)['ConvertCodeThatCanStartToReturnNil'] && lhs_not_nil_check
            next unless style_offending_node?(node, lhs_receiver, rhs, rhs_receiver)

            lhs_method_chain = style_find_method_chain(lhs_receiver)
            next unless lhs_method_chain == lhs_receiver || lhs_not_nil_check

            style_report_offense(
              node,
              rhs, rhs_receiver,
              @style_host.send(:range_with_surrounding_space, range: lhs.source_range, side: :right),
              @style_host.send(:range_with_surrounding_space, range: lhs_operator_range, side: :right),
              offense_range: @style_host.send(:range_between, lhs.source_range.begin_pos, rhs.source_range.end_pos)
            )
          end
        end

        def run_consistency_and(host, node)
          @consistency_host = host
          @consistency_node = node
          @consistency_operands = []
          all_operands = consistency_collect_operands(node, [])
          operand_groups = all_operands.group_by { |operand| consistency_receiver_name_as_key(operand, +'') }

          operand_groups.each_value do |grouped_operands|
            next unless (dot_op, begin_of_rest_operands = consistency_find_consistent_parts(grouped_operands))

            rest_operands = grouped_operands[begin_of_rest_operands..]
            rest_operands.each do |operand|
              next if consistency_already_appropriate_call?(operand, dot_op)

              consistency_register_offense(operand, dot_op)
            end
          end
        end

        def run_redundant_csend(host, node)
          @redundant_host = host
          @redundant_node = node
          @redundant_receiver = node.receiver
          unless redundant_assume_receiver_instance_exists?(node.receiver)
            return unless redundant_check?(node) && @redundant_host.send(:allowed_method?, node.method_name)
            return if redundant_respond_to_nil_specific_method?(node)
          end

          range = node.loc.dot
          @redundant_host.add_offense(range) { |corrector| corrector.replace(range, '.') }
        end

        def run_redundant_or(host, node)
          @redundant_host = host
          @redundant_node = node
          @redundant_receiver = node
          redundant_conversion_with_default?(node) do |send_node|
            range = send_node.loc.dot.begin.join(node.source_range.end)

            @redundant_host.add_offense(range, message: REDUNDANT_MSG_LITERAL) do |corrector|
              corrector.replace(send_node.loc.dot, '.')

              range_with_default = node.lhs.source_range.end.begin.join(node.source_range.end)
              corrector.remove(range_with_default)
            end
          end
        end

        def run_empty_check(host, node)
          @empty_host = host
          @empty_node = node
          @empty_condition = node.condition
          return unless empty_nav_in_conditional?(node)

          condition = node.condition
          @empty_host.add_offense(condition) do |corrector|
            receiver = empty_condition_receiver_source(condition)
            corrector.replace(condition, "#{receiver} && #{receiver}.#{condition.method_name}")
          end
        end

        def run_chain_length(host, node)
          @chain_host = host
          @chain_node = node
          @chain_nodes = []
          chains = chain_length_collect(node)
          return if chains.size < chain_length_max

          @chain_host.add_offense(chains.last, message: format(CHAIN_LENGTH_MSG, max: chain_length_max))
        end

        def run_operator_method_call(host, node)
          @operator_host = host
          @operator_node = node
          @operator_dot = node.loc.dot
          return unless operator_dot_present?(node)
          return if node.receiver.const_type? || !operator_single_argument?(node)
          return unless (rhs = node.first_argument)
          return if operator_method_call_with_parenthesized_arg?(rhs)
          return if operator_invalid_syntax_argument?(rhs)

          @operator_host.add_offense(@operator_dot) do |corrector|
            operator_wrap_in_parentheses_if_chained(corrector, node)
            corrector.replace(@operator_dot, ' ')

            selector = node.loc.selector
            corrector.insert_after(selector, ' ') if operator_insert_space_after?(node)
          end
        end

        def run_omit_parentheses(host, node)
          @paren_host = host
          @paren_node = node
          @paren_config = host.send(:cop_config)
          omit_parentheses_for_call
        end

        def run_require_parentheses(host, node)
          @paren_host = host
          @paren_node = node
          @paren_config = host.send(:cop_config)
          require_parentheses_for_call
        end

        def run_without_parens_send(host, node)
          @without_host = host
          @without_node = node
          @without_name = node.method_name
          return unless !node.arguments? && node.parenthesized?
          return if without_ineligible_node?(node)
          return if without_default_argument?(node)
          return if without_allowed_method_name?(node.method_name)
          return if without_same_name_assignment?(node)
          return if without_parenthesized_it_method_in_block?(node)

          without_register_offense(node)
        end

        def run_space_send(host, node)
          @space_host = host
          @space_node = node
          @space_dot = node.loc.dot
          return unless space_dot_operator?(node)

          space_check_before_dot(node)
          space_check_after_dot(node)
        end

        def run_space_const(host, node)
          @space_host = host
          @space_node = node
          @space_dot = node.loc
          return unless space_double_colon?(node)

          space_check_after_double_colon(node)
        end

        def run_ambiguous_operator(host)
          @ambiguous_host = host
          @ambiguous_source = host.processed_source
          @ambiguous_ast = @ambiguous_source.ast
          return unless @ambiguous_ast

          @ambiguous_source.diagnostics.each do |diagnostic|
            next unless ambiguous_prefix_reason?(diagnostic)

            offense_node = ambiguous_find_offense_node_by(diagnostic)
            next unless offense_node

            message = ambiguous_format_message(diagnostic)
            @ambiguous_host.add_offense(
              diagnostic.location, message: message, severity: diagnostic.level
            ) do |corrector|
              @ambiguous_host.send(:add_parentheses, offense_node, corrector)
            end
          end
        end

        def run_precedence_prepare(host)
          @precedence_host = host
          @precedence_map = {}
          @precedence_node = host
        end

        def run_precedence_and(host, node)
          @precedence_host = host
          @precedence_node = node
          @precedence_map ||= {}
          return unless (parent = node.parent)
          return if parent.begin_type?
          return unless parent.or_type?

          @precedence_host.add_offense(node) do |corrector|
            precedence_autocorrect(corrector, node)
          end
        end

        def run_precedence_send(host, node)
          @precedence_host = host
          @precedence_node = node
          @precedence_map ||= {}
          return if node.parenthesized?
          return unless (parent = node.parent)
          return unless precedence_operator?(parent)
          return unless precedence_greater?(node, parent)

          @precedence_host.add_offense(node) do |corrector|
            precedence_autocorrect(corrector, node)
          end
        end

        private

        def require_safe_navigation?(node)
          @nav_send = node
          parent = node.parent
          return true unless parent&.and_type?

          parent.rhs != node || parent.lhs.receiver != parent.rhs.receiver
        end

        # @param [Parser::Source::Range] offense_range
        # @param [RuboCop::AST::SendNode] send_node
        # @return [String]
        def add_safe_navigation_operator(offense_range:, send_node:)
          @nav_send = send_node
          source =
            if brackets?(send_node)
              format(
                '%<method_name>s(%<arguments>s)%<method_chain>s',
                arguments: send_node.arguments.map(&:source).join(', '),
                method_name: send_node.method_name,
                method_chain: send_node.source_range.end.join(send_node.source_range.end).source
              )
            else
              offense_range.source
            end
          source.prepend('.') unless source.start_with?('.')
          source.prepend('&')
        end

        # @param [RuboCop::Cop::Corrector] corrector
        # @param [Parser::Source::Range] offense_range
        # @param [RuboCop::AST::SendNode] send_node
        def autocorrect(corrector, offense_range:, send_node:)
          @nav_send = send_node
          corrector.replace(
            offense_range,
            add_safe_navigation_operator(offense_range: offense_range, send_node: send_node)
          )

          corrector.wrap(send_node, '(', ')') if require_parentheses?(send_node)
        end

        def brackets?(send_node)
          @nav_send = send_node
          send_node.method?(:[]) || send_node.method?(:[]=)
        end

        def require_parentheses?(send_node)
          return false unless send_node.comparison_method?
          return false unless (node = send_node.parent)

          (node.respond_to?(:logical_operator?) && node.logical_operator?) ||
            (node.respond_to?(:comparison_method?) && node.comparison_method?)
        end

        def style_report_offense(node, rhs, rhs_receiver, *removal_ranges, offense_range: node)
          host = @style_host
          @style_chain = rhs
          host.add_offense(offense_range) do |corrector|
            next if style_and_with_rhs_or?(node)

            removal_ranges.each { |range| corrector.remove(range) }
            yield corrector if block_given?

            style_handle_comments(corrector, node, rhs)
            style_add_safe_nav_to_all_methods_in_chain(corrector, rhs_receiver, rhs)
          end
        end

        def style_find_method_chain(node)
          @style_host = @style_host
          @style_chain = node if node
          return node unless node&.parent&.call_type?

          style_find_method_chain(node.parent)
        end

        def style_collect_and_clauses(node)
          @style_host = @style_host
          @style_node = node
          node.each_descendant(:and)
              .inject(style_and_parts(node)) { |nodes, and_node| style_concat_nodes(nodes, and_node) }
              .sort_by { |a| a.is_a?(RuboCop::AST::Node) ? a.source_range.begin_pos : a.begin_pos }
              .each_slice(2)
              .each_cons(2)
        end

        def style_concat_nodes(nodes, and_node)
          @style_host = @style_host
          @style_chain = and_node
          return nodes if and_node.each_ancestor(:block).any?

          nodes.concat(style_and_parts(and_node))
        end

        def style_and_parts(node)
          @style_host = @style_host
          @style_node = node
          parts = [node.loc.operator]
          parts << node.rhs unless style_and_inside_begin?(node.rhs)
          parts << node.lhs unless node.lhs.and_type? || style_and_inside_begin?(node.lhs)
          parts
        end

        def style_offending_node?(node, lhs_receiver, rhs, rhs_receiver)
          @style_host = @style_host
          @style_chain = rhs
          return false if lhs_receiver != rhs_receiver || rhs_receiver.nil?
          return false if style_use_var_only_in_unless_modifier?(node, lhs_receiver)
          return false if style_chain_length(rhs, rhs_receiver) > style_max_chain_length
          return false if style_unsafe_method_used?(rhs, rhs_receiver.parent)
          return false if style_empty_predicate?(rhs)

          true
        end

        def style_use_var_only_in_unless_modifier?(node, variable)
          @style_host = @style_host
          @style_node = node
          node.if_type? && node.unless? && !style_method_called?(variable)
        end

        def style_extract_if_body(node)
          @style_host = @style_host
          @style_node = node
          if node.ternary?
            node.branches.find { |branch| !branch.nil_type? }
          else
            node.node_parts[1]
          end
        end

        def style_handle_comments(corrector, node, method_call)
          @style_host = @style_host
          @style_chain = method_call
          comments = style_comments(node)
          return if comments.empty?

          corrector.insert_before(method_call, "#{comments.map(&:text).join("\n")}\n")
        end

        def style_comments(node)
          @style_node = node
          style_relevant_comment_ranges(node).each.with_object([]) do |range, comments|
            comments.concat(@style_host.processed_source.each_comment_in_lines(range).to_a)
          end
        end

        def style_relevant_comment_ranges(node)
          @style_host = @style_host
          @style_node = node
          begin_pos = node.loc.first_line
          end_pos = node.loc.last_line

          node.child_nodes.each.with_object([]) do |child, ranges|
            ranges << (begin_pos...child.loc.first_line)
            begin_pos = child.loc.last_line
          end << (begin_pos...end_pos)
        end

        def style_allowed_if_condition?(node)
          @style_host = @style_host
          @style_node = node
          node.else? || node.elsif?
        end

        def style_extract_parts_from_if(node)
          @style_host = @style_host
          @style_node = node
          variable, receiver =
            if node.ternary?
              style_ternary_candidate(node)
            else
              style_modifier_if_candidate(node)
            end

          checked_variable, matching_receiver, method = style_extract_common_parts(receiver, variable)
          matching_receiver = nil if receiver && STYLE_LOGIC_JUMP_KEYWORDS.include?(receiver.type)
          [checked_variable, matching_receiver, receiver, method]
        end

        def style_extract_common_parts(method_chain, checked_variable)
          @style_host = @style_host
          @style_chain = method_chain
          matching_receiver = style_find_matching_receiver_invocation(method_chain, checked_variable)
          method = matching_receiver.parent if matching_receiver
          [checked_variable, matching_receiver, method]
        end

        def style_find_matching_receiver_invocation(method_chain, checked_variable)
          @style_host = @style_host
          @style_chain = method_chain
          return nil unless method_chain.respond_to?(:receiver)

          receiver = method_chain.receiver
          return receiver if receiver == checked_variable

          style_find_matching_receiver_invocation(receiver, checked_variable)
        end

        def style_chain_length(method_chain, method)
          @style_host = @style_host
          @style_chain = method_chain
          method.each_ancestor(:send, :csend).inject(0) do |total, ancestor|
            break total + 1 if ancestor == method_chain

            total + 1
          end
        end

        def style_unsafe_method_used?(method_chain, method)
          @style_chain = method_chain
          return true if style_unsafe_method?(method)

          method.each_ancestor(:send).any? do |ancestor|
            break true unless @style_host.config.cop_enabled?('Lint/SafeNavigationChain')
            break true if style_unsafe_method?(ancestor)
            break true if @style_host.send(:nil_methods).include?(ancestor.method_name)
            break false if ancestor == method_chain
          end
        end

        def style_unsafe_method?(send_node)
          @style_host = @style_host
          @style_node = send_node
          style_negated?(send_node) ||
            style_assignment_call?(send_node) ||
            style_bare_operator?(send_node)
        end

        def style_negated?(send_node)
          @style_host = @style_host
          @style_node = send_node
          if style_method_called?(send_node)
            style_negated?(send_node.parent)
          else
            send_node.send_type? && send_node.method?(:!)
          end
        end

        def style_method_called?(send_node)
          @style_host = @style_host
          @style_node = send_node
          send_node&.parent&.send_type?
        end

        def style_begin_range(node, method_call)
          @style_chain = method_call
          @style_host.send(:range_between, node.source_range.begin_pos, method_call.source_range.begin_pos)
        end

        def style_end_range(node, method_call)
          @style_chain = method_call
          @style_host.send(:range_between, method_call.source_range.end_pos, node.source_range.end_pos)
        end

        def style_add_safe_nav_to_all_methods_in_chain(corrector, start_method, method_chain)
          @style_host = @style_host
          @style_chain = method_chain
          start_method.each_ancestor do |ancestor|
            break unless %i[send block].include?(ancestor.type)
            next unless ancestor.send_type?
            next if ancestor.safe_navigation?

            corrector.insert_before(ancestor.loc.dot, '&')
            break if ancestor == method_chain
          end
        end

        def style_max_chain_length
          host = @style_host
          host.send(:cop_config).fetch('MaxChainLength', 2)
        end

        def consistency_collect_operands(node, operand_nodes)
          @consistency_node = node
          @consistency_operands = operand_nodes
          consistency_operand_nodes(node.lhs, operand_nodes)
          consistency_operand_nodes(node.rhs, operand_nodes)
          operand_nodes
        end

        def consistency_receiver_name_as_key(method, fully_receivers)
          @consistency_node = method
          if method.parent.call_type?
            receiver(method.parent, fully_receivers)
          else
            fully_receivers << method.receiver&.source.to_s
          end
        end

        def consistency_find_consistent_parts(grouped_operands)
          @consistency_operands = grouped_operands
          csend_in_and, csend_in_or, send_in_and, send_in_or = consistency_most_left_indices(grouped_operands)
          return if csend_in_and && csend_in_or && csend_in_and < csend_in_or

          if csend_in_and
            ['.', (send_in_and ? [send_in_and, csend_in_and].min : csend_in_and) + 1]
          elsif send_in_or && csend_in_or
            send_in_or < csend_in_or ? ['.', send_in_or + 1] : ['&.', csend_in_or + 1]
          elsif send_in_and && csend_in_or && send_in_and < csend_in_or
            ['.', csend_in_or]
          end
        end

        def consistency_already_appropriate_call?(operand, dot_op)
          @consistency_node = operand
          return true if consistency_safe_call?(operand) && dot_op == '&.'

          consistency_dot_or_operator?(operand) && dot_op == '.'
        end

        def consistency_register_offense(operand, dot_operator)
          @consistency_node = operand
          offense_range = operand.operator_method? ? operand : operand.loc.dot
          message = dot_operator == '.' ? USE_DOT_MSG : USE_SAFE_NAVIGATION_MSG

          @consistency_host.add_offense(offense_range, message: message) do |corrector|
            next if operand.operator_method?

            corrector.replace(operand.loc.dot, dot_operator)
          end
        end

        def consistency_operand_nodes(operand, operand_nodes)
          @consistency_operands = operand_nodes
          if operand.operator_keyword?
            consistency_collect_operands(operand, operand_nodes)
          elsif operand.call_type?
            operand_nodes << operand
          end
        end

        def consistency_most_left_indices(grouped_operands)
          @consistency_operands = grouped_operands
          indices = { csend_in_and: nil, csend_in_or: nil, send_in_and: nil, send_in_or: nil }

          grouped_operands.each_with_index do |operand, index|
            indices[:csend_in_and] ||= index if consistency_operand_in_and?(operand) && operand.csend_type?
            indices[:csend_in_or] ||= index if consistency_operand_in_or?(operand) && operand.csend_type?
            indices[:send_in_and] ||= index if consistency_operand_in_and?(operand) && !consistency_nilable?(operand)
            indices[:send_in_or] ||= index if consistency_operand_in_or?(operand) && !consistency_nilable?(operand)
          end

          indices.values
        end

        def consistency_operand_in_and?(node)
          @consistency_node = node
          return true if node.parent.and_type?

          parent = node.parent.parent while node.parent.begin_type?
          parent&.and_type?
        end

        def consistency_operand_in_or?(node)
          @consistency_node = node
          return true if node.parent.or_type?

          parent = node.parent.parent while node.parent.begin_type?
          parent&.or_type?
        end

        def consistency_nilable?(node)
          @consistency_node = node
          node.csend_type? || @consistency_host.send(:nil_methods).include?(node.method_name)
        end

        def redundant_assume_receiver_instance_exists?(receiver)
          @redundant_receiver = receiver
          redundant_literal_receiver?(receiver)
        end

        def redundant_check?(node)
          @redundant_node = node
          parent = node.parent
          return false unless parent

          redundant_condition?(parent, node) ||
            parent.operator_keyword? ||
            (parent.send_type? && parent.negation_method?)
        end

        def redundant_condition?(parent, node)
          @redundant_node = node
          (parent.conditional? || parent.post_condition_loop?) && parent.condition == node
        end

        def chain_length_collect(node)
          @chain_node = node
          @chain_nodes = node.each_ancestor.with_object([]) do |parent, chains|
            break chains unless parent.csend_type?

            chains << parent
          end
        end

        def chain_length_max
          host = @chain_host
          host.send(:cop_config)['Max'] || 2
        end

        def operator_method_call_with_parenthesized_arg?(argument)
          @operator_node = argument
          return false unless argument.parent.parent&.send_type?

          argument.children.first && argument.parent.parenthesized?
        end

        def operator_invalid_syntax_argument?(argument)
          @operator_node = argument
          type = argument.hash_type? ? argument.children.first&.type : argument.type
          OPERATOR_INVALID_ARG_TYPES.include?(type)
        end

        def operator_wrap_in_parentheses_if_chained(corrector, node)
          @operator_node = node
          return unless node.parent&.call_type?
          return if node.parent.first_argument == node

          operator = node.loc.selector
          ::RuboCop::Cop::ParenthesesCorrector.correct(corrector, node)
          corrector.insert_after(operator, ' ')
          corrector.wrap(node, '(', ')')
        end

        def operator_insert_space_after?(node)
          @operator_node = node
          rhs = node.first_argument
          selector = node.loc.selector
          return true if selector.end_pos == rhs.source_range.begin_pos
          return false if node.parent&.call_type?

          range = selector.end.join(rhs.source_range.begin)
          return true if node.method?(:/) && range.source == '('

          false
        end

        def omit_parentheses_for_call
          node = @paren_node
          return unless node.parenthesized?
          return if omit_inside_endless_method_def?(node)
          return if omit_require_parentheses_for_hash_value_omission?(node)
          return if omit_syntax_like_method_call?(node)
          return if omit_method_call_before_constant_resolution?(node)
          return if omit_super_call_without_arguments?(node)
          return if omit_legitimate_call_with_parentheses?(node)
          return if omit_allowed_camel_case_method_call?(node)
          return if omit_allowed_string_interpolation_method_call?(node)

          @paren_host.add_offense(omit_offense_range(node), message: OMIT_PARENS_MSG) do |corrector|
            omit_autocorrect(corrector, node)
          end
        end

        def omit_autocorrect(corrector, node)
          @paren_node = node
          range = paren_args_begin(node)
          if omit_parentheses_at_the_end_of_multiline_call?(node)
            with_whitespace = @paren_host.send(:range_with_surrounding_space, range, side: :right, newlines: false)
            corrector.replace(with_whitespace, ' \\')
          else
            corrector.replace(range, ' ')
          end
          corrector.remove(node.loc.end)
        end

        def omit_offense_range(node)
          @paren_node = node
          node.loc.begin.join(node.loc.end)
        end

        def omit_inside_endless_method_def?(node)
          @paren_node = node
          node.each_ancestor(:def, :defs).any?(&:endless?) && node.arguments.any?
        end

        def omit_require_parentheses_for_hash_value_omission?(node)
          @paren_node = node
          return false unless (last_argument = node.last_argument)
          return false if !last_argument.hash_type? || !last_argument.pairs.last&.value_omission?

          node.parent&.conditional? || node.parent&.single_line? || !omit_last_expression?(node)
        end

        def omit_last_expression?(node)
          @paren_node = node
          !(node.parent&.assignment? ? node.parent.right_sibling : node.right_sibling)
        end

        def omit_syntax_like_method_call?(node)
          @paren_node = node
          node.implicit_call? || node.operator_method?
        end

        def omit_method_call_before_constant_resolution?(node)
          @paren_node = node
          node.parent&.const_type?
        end

        def omit_super_call_without_arguments?(node)
          @paren_node = node
          node.super_type? && node.arguments.none?
        end

        def omit_allowed_camel_case_method_call?(node)
          @paren_node = node
          node.camel_case_method? &&
            (node.arguments.none? || @paren_config['AllowParenthesesInCamelCaseMethod'])
        end

        def omit_allowed_string_interpolation_method_call?(node)
          @paren_node = node
          @paren_config['AllowParenthesesInStringInterpolation'] &&
            omit_inside_string_interpolation?(node)
        end

        def omit_parentheses_at_the_end_of_multiline_call?(node)
          @paren_node = node
          node.multiline? &&
            node.loc.begin.source_line.gsub(TRAILING_WHITESPACE_REGEX, '').end_with?('(')
        end

        def omit_legitimate_call_with_parentheses?(node)
          @paren_node = node
          omit_call_in_literals?(node) ||
            node.parent&.when_type? ||
            omit_call_with_ambiguous_arguments?(node) ||
            omit_call_in_logical_operators?(node) ||
            omit_call_in_optional_arguments?(node) ||
            omit_call_in_single_line_inheritance?(node) ||
            omit_allowed_multiline_call_with_parentheses?(node) ||
            omit_allowed_chained_call_with_parentheses?(node) ||
            omit_assignment_in_condition?(node) ||
            omit_forwards_anonymous_rest_arguments?(node)
        end

        def omit_call_in_literals?(node)
          @paren_node = node
          parent = node.parent&.block_type? ? node.parent.parent : node.parent
          return false unless parent

          omit_parent_pair_or_array?(parent) ||
            omit_splat?(parent) ||
            omit_ternary_if?(parent)
        end

        def omit_call_in_logical_operators?(node)
          @paren_node = node
          parent = node.parent&.block_type? ? node.parent.parent : node.parent
          return false unless parent

          omit_logical_operator?(parent) ||
            (parent.send_type? &&
            parent.arguments.any? { |argument| omit_logical_operator?(argument) })
        end

        def omit_call_in_optional_arguments?(node)
          @paren_node = node
          node.parent && (node.parent.optarg_type? || node.parent.kwoptarg_type?)
        end

        def omit_call_in_single_line_inheritance?(node)
          @paren_node = node
          node.parent&.class_type? && node.parent.single_line?
        end

        def omit_call_with_ambiguous_arguments?(node)
          @paren_node = node
          omit_call_with_braced_block?(node) ||
            omit_call_in_argument_with_block?(node) ||
            omit_call_as_argument_or_chain?(node) ||
            omit_call_in_match_pattern?(node) ||
            omit_hash_literal_in_arguments?(node) ||
            omit_ambiguous_range_argument?(node) ||
            node.descendants.any? do |n|
              n.forwarded_args_type? || n.block_type? || n.numblock_type? ||
                omit_ambiguous_literal?(n) || omit_logical_operator?(n)
            end
        end

        def omit_call_with_braced_block?(node)
          @paren_node = node
          (node.call_type? || node.super_type?) && node.block_node&.braces?
        end

        def omit_call_in_argument_with_block?(node)
          @paren_node = node
          parent = node.parent&.block_type? && node.parent.parent
          return false unless parent

          parent.call_type? || parent.super_type? || parent.yield_type?
        end

        def omit_call_as_argument_or_chain?(node)
          @paren_node = node
          node.parent &&
            (node.parent.call_type? || node.parent.super_type? || node.parent.yield_type?) &&
            !omit_assigned_before?(node.parent, node)
        end

        def omit_call_in_match_pattern?(node)
          @paren_node = node
          return false unless (parent = node.parent)

          parent.match_pattern_type? || parent.match_pattern_p_type?
        end

        def omit_hash_literal_in_arguments?(node)
          @paren_node = node
          node.arguments.any? do |n|
            omit_hash_literal?(n) ||
              (n.send_type? && node.descendants.any? { |descendant| omit_hash_literal?(descendant) })
          end
        end

        def omit_ambiguous_range_argument?(node)
          @paren_node = node
          return true if (first_arg = node.first_argument)&.range_type? && first_arg.begin.nil?
          return true if (last_arg = node.last_argument)&.range_type? && last_arg.end.nil?

          false
        end

        def omit_allowed_multiline_call_with_parentheses?(node)
          @paren_node = node
          @paren_config['AllowParenthesesInMultilineCall'] && node.multiline?
        end

        def omit_allowed_chained_call_with_parentheses?(node)
          @paren_node = node
          return false unless @paren_config['AllowParenthesesInChaining']

          previous = node.descendants.first
          return false unless previous&.send_type?

          previous.parenthesized? || omit_allowed_chained_call_with_parentheses?(previous)
        end

        def omit_ambiguous_literal?(node)
          @paren_node = node
          omit_splat?(node) || omit_ternary_if?(node) || omit_regexp_slash_literal?(node) || omit_unary_literal?(node)
        end

        def omit_splat?(node)
          @paren_node = node
          node.splat_type? || node.kwsplat_type? || node.block_pass_type?
        end

        def omit_ternary_if?(node)
          @paren_node = node
          node.if_type? && node.ternary?
        end

        def omit_logical_operator?(node)
          @paren_node = node
          node.operator_keyword? && node.logical_operator?
        end

        def omit_hash_literal?(node)
          @paren_node = node
          node.hash_type? && node.braces?
        end

        def omit_regexp_slash_literal?(node)
          @paren_node = node
          node.regexp_type? && node.loc.begin.source == '/'
        end

        def omit_unary_literal?(node)
          @paren_node = node
          (node.numeric_type? && node.sign?) ||
            (node.parent&.send_type? && node.parent.unary_operation?)
        end

        def omit_assigned_before?(node, target)
          @paren_node = node
          node.assignment? && node.loc.operator.begin < target.loc.begin
        end

        def omit_inside_string_interpolation?(node)
          @paren_node = node
          node.ancestors.drop_while { |a| !a.begin_type? }.any?(&:dstr_type?)
        end

        def omit_assignment_in_condition?(node)
          @paren_node = node
          parent = node.parent
          return false unless parent

          grandparent = parent.parent
          return false unless grandparent

          parent.assignment? && (grandparent.conditional? || grandparent.when_type?)
        end

        def omit_forwards_anonymous_rest_arguments?(node)
          @paren_node = node
          return false unless (last_argument = node.last_argument)
          return true if last_argument.forwarded_restarg_type?

          last_argument.hash_type? && last_argument.children.first&.forwarded_kwrestarg_type?
        end

        def require_parentheses_for_call
          node = @paren_node
          return if require_allowed_method_name?(node.method_name)
          return if @paren_host.send(:matches_allowed_pattern?, node.method_name)
          return if require_eligible_for_parentheses_omission?(node)
          return unless node.arguments? && !node.parenthesized?

          @paren_host.add_offense(node, message: REQUIRE_PARENS_MSG) do |corrector|
            corrector.replace(paren_args_begin(node), '(')
            corrector.insert_after(paren_args_end(node), ')') unless paren_args_parenthesized?(node)
          end
        end

        def require_allowed_method_name?(name)
          host = @paren_host
          host.send(:allowed_method?, name) || host.send(:matches_allowed_pattern?, name)
        end

        def require_eligible_for_parentheses_omission?(node)
          @paren_node = node
          node.operator_method? || node.setter_method? || require_ignored_macro?(node)
        end

        def require_included_macros_list
          config = @paren_config
          config.fetch('IncludedMacros', []).map(&:to_sym)
        end

        def require_ignored_macro?(node)
          @paren_node = node
          @paren_config['IgnoreMacros'] &&
            node.macro? &&
            !require_included_macros_list.include?(node.method_name)
        end

        def paren_args_begin(node)
          @paren_node = node
          loc = node.loc
          selector = node.yield_type? ? loc.keyword : loc.selector
          resize_by = paren_args_parenthesized?(node) ? 2 : 1
          selector.end.resize(resize_by)
        end

        def paren_args_end(node)
          @paren_node = node
          node.source_range.end
        end

        def paren_args_parenthesized?(node)
          @paren_node = node
          return false unless node.arguments.one?

          first_node = node.first_argument
          first_node.begin_type? && first_node.parenthesized_call?
        end

        def without_register_offense(node)
          @without_node = node
          @without_host.add_offense(without_offense_range(node)) do |corrector|
            corrector.remove(node.loc.begin)
            corrector.remove(node.loc.end)
          end
        end

        def without_ineligible_node?(node)
          @without_node = node
          without_camel_or_implicit?(node)
        end

        def without_default_argument?(node)
          @without_node = node
          node.parent&.optarg_type?
        end

        def without_allowed_method_name?(name)
          host = @without_host
          @without_name = name
          host.send(:allowed_method?, name) || host.send(:matches_allowed_pattern?, name)
        end

        def without_same_name_assignment?(node)
          @without_node = node
          return false if node.receiver

          without_any_assignment?(node) do |asgn_node|
            if asgn_node.masgn_type?
              without_variable_in_mass_assignment?(node.method_name, asgn_node)
            else
              asgn_node.loc.name.source == node.method_name.to_s
            end
          end
        end

        def without_parenthesized_it_method_in_block?(node)
          @without_node = node
          return false unless node.method?(:it)
          return false unless (block_node = node.each_ancestor(:block).first)
          return false unless block_node.arguments.empty_and_without_delimiters?

          !node.receiver && node.arguments.empty? && !node.block_literal?
        end

        def without_any_assignment?(node)
          @without_node = node
          node.each_ancestor(*AST::Node::ASSIGNMENTS).any? do |asgn_node|
            next if asgn_node.shorthand_asgn? && asgn_node.lhs.call_type?

            yield asgn_node
          end
        end

        def without_variable_in_mass_assignment?(variable_name, node)
          @without_node = node
          @without_name = variable_name
          node.assignments.reject(&:send_type?).any? { |n| n.name == variable_name }
        end

        def without_offense_range(node)
          @without_node = node
          node.loc.begin.join(node.loc.end)
        end

        def space_check_before_dot(node)
          @space_node = node
          receiver_pos = node.receiver.source_range.end_pos
          dot_pos = node.loc.dot.begin_pos
          space_check_space(receiver_pos, dot_pos)
        end

        def space_check_after_dot(node)
          @space_node = node
          dot_pos = node.loc.dot.end_pos
          selector_pos =
            if node.method?(:call) && !node.loc.selector
              node.loc.begin.begin_pos
            else
              node.loc.selector.begin_pos
            end
          space_check_space(dot_pos, selector_pos)
        end

        def space_check_after_double_colon(node)
          @space_node = node
          double_colon_pos = node.loc.double_colon.end_pos
          name_pos = node.loc.name.begin_pos
          space_check_space(double_colon_pos, name_pos)
        end

        def space_check_space(begin_pos, end_pos)
          host = @space_host
          return if end_pos <= begin_pos

          range = host.send(:range_between, begin_pos, end_pos)
          return unless range.source.match?(SPACES_REGEXP)

          host.add_offense(range) { |corrector| corrector.remove(range) }
        end

        def ambiguous_find_offense_node_by(diagnostic)
          ast = @ambiguous_ast
          ast.each_node(:splat, :block_pass, :kwsplat) do |node|
            next unless ambiguous_offense_position?(node, diagnostic)

            found = ambiguous_offense_node(node)
            return found if found
          end

          ast.each_node(:send).find do |send_node|
            first_argument = send_node.first_argument
            first_argument &&
              ambiguous_offense_position?(first_argument, diagnostic) &&
              ambiguous_unary_operator?(first_argument, diagnostic)
          end
        end

        def ambiguous_format_message(diagnostic)
          @ambiguous_source = @ambiguous_source
          operator = diagnostic.location.source
          hash = AMBIGUITIES[operator]
          format(AMBIGUOUS_MSG_FORMAT, hash)
        end

        def ambiguous_offense_position?(node, diagnostic)
          @ambiguous_ast = @ambiguous_ast
          node.source_range.begin_pos == diagnostic.location.begin_pos
        end

        def ambiguous_offense_node(node)
          @ambiguous_source = @ambiguous_source
          case node.type
          when :splat, :block_pass
            node.parent
          when :kwsplat
            node.parent.parent
          end
        end

        def ambiguous_unary_operator?(node, diagnostic)
          @ambiguous_ast = @ambiguous_ast
          node.source.start_with?(diagnostic.arguments[:prefix])
        end

        def precedence_lookup(node)
          @precedence_node = node
          @precedence_map.fetch(node) do
            PRECEDENCE_GROUPS.index { |operators| operators.include?(precedence_operator_name(node)) }
          end
        end

        def precedence_operator?(node)
          @precedence_node = node
          (node.send_type? && PRECEDENCE_OPERATORS.include?(node.method_name)) || node.operator_keyword?
        end

        def precedence_greater?(node1, node2)
          @precedence_node = node1
          node1_precedence = precedence_lookup(node1)
          node2_precedence = precedence_lookup(node2)
          return false unless node1_precedence && node2_precedence

          node2_precedence > node1_precedence
        end

        def precedence_operator_name(node)
          @precedence_node = node
          if node.send_type?
            node.method_name
          else
            node.operator.to_sym
          end
        end

        def precedence_autocorrect(corrector, node)
          @precedence_node = node
          corrector.wrap(node, '(', ')')
        end

        def style_assignment_call?(send_node)
          @style_host = @style_host
          @style_node = send_node
          send_node.assignment?
        end

        def style_bare_operator?(send_node)
          @style_host = @style_host
          @style_node = send_node
          !send_node.dot? && !send_node.safe_navigation?
        end

        def style_empty_predicate?(node)
          @style_host = @style_host
          @style_chain = node
          node.send_type? && node.method?(:empty?)
        end

        def consistency_safe_call?(operand)
          @consistency_node = operand
          operand.safe_navigation?
        end

        def consistency_dot_or_operator?(operand)
          @consistency_node = operand
          operand.dot? || operand.operator_method?
        end

        def redundant_literal_receiver?(receiver)
          @redundant_receiver = receiver
          return true if receiver.const_type? && !receiver.short_name.match?(SNAKE_CASE)

          receiver.self_type? || (receiver.literal? && !receiver.nil_type?)
        end

        def empty_condition_receiver_source(condition)
          @empty_condition = condition
          condition.receiver.source
        end

        def operator_dot_present?(node)
          @operator_node = node
          !node.loc.dot.nil?
        end

        def operator_single_argument?(node)
          @operator_node = node
          node.arguments.one?
        end

        def space_dot_operator?(node)
          @space_node = node
          node.dot? || node.safe_navigation?
        end

        def space_double_colon?(node)
          @space_node = node
          node.loc.respond_to?(:double_colon) && !node.loc.double_colon.nil?
        end

        def ambiguous_prefix_reason?(diagnostic)
          @ambiguous_source = @ambiguous_source
          diagnostic.reason == :ambiguous_prefix
        end

        def without_camel_or_implicit?(node)
          @without_node = node
          node.camel_case_method? || node.implicit_call? || node.prefix_not?
        end

        def omit_parent_pair_or_array?(parent)
          @paren_node = parent
          parent.pair_type? || parent.array_type? || parent.range_type?
        end

      end
    end
  end
end

